"""Presentation of the shared causal inventory, outside the numerical core."""
from film_foundry.ui.qt import QtWidgets
from film_foundry.ui.curve_editor import text
from film_foundry.core.process_couplings import describe_process_couplings

# (condition, linked response, interpretation), in both interface languages.
LINKS={
 'film_storage_time':(('储存时长与感度损失','Storage duration and speed loss'),('期望按各层平均损失档数反求明确储存天数，同时产生材料声明的储存雾；各层失速不同可偏色。只作用于曝光前材料，已有潜影不重写。目标属于选中时间段，不是整段历史或最终RGB。','Desired mean layer speed loss resolves to explicit storage days, also producing stock-defined fog. Unequal speed loss can shift colour. Only pre-exposure stock changes; saved latent stays frozen. The target is per segment, not the whole history or final RGB.'),('同一时钟／感度与雾','One clock / speed and fog')),
 'film_latent_time':(('等待时长与潜影反差','Waiting and latent contrast'),('潜影等待同时发生衰退和生雾。期望控制原始激活差异的平均收缩量，并公布附带的灰雾偏移；不是直接减淡整张照片。温湿度和各层速率决定可达范围。','Latent waiting combines fading with fogging. The target controls mean contraction of original activation differences and reports the fog offset; it does not directly fade the image. Temperature, humidity and layer rates bound reachability.'),('竞争响应／非成片反差','Competing response / not final contrast')),
 'film_light_time':(('受光时长与残盐转银','Light duration and salt conversion'),('期望按剩余原始银盐的各层平均转化比例求时长；漂白盐、表面盐也按材料响应参与。残盐空间分布决定实际增银量，没有盐就没有变化；这不是整片含银比例或变黑程度。扫描不会推进受光。','Desired mean layer conversion of surviving original halide resolves to duration; bleached and surface salts follow their material responses. Actual silver gain depends on surviving salt distribution; no salt means no change. This is not total silver fraction or image darkening. Scans never advance exposure.'),('剩余库存／同一受光','Surviving inventory / shared light')),
 'surface_salt_light':(('表面残盐受光','Surface salt in light'),('漂白后未清除的表面盐可在末段受光转银，增加透射密度并参与表面反射；已定影或机械移出的盐不会恢复。与主体残盐共用显式时长，观看不继续变黑。','Uncleared bleached surface salt can convert to silver in the final light stage, affecting transmission and surface reflection. Fixed or removed salt cannot return. Shares the primary salt light clock; observation does not continue darkening.'),('实际残盐／只读观察','Retained salt / read-only observation')),
 'emulsion_shear':(('乳剂剪切与出框','Emulsion shear and frame loss'),('压力、时长、硬化与湿润共同决定水平拖移。银盐、银、染料、潜影及乳剂所属沉积随之移动；后续药浴在新位置接触。片基/背层不动，出框部分记账移出，反向拖动不能取回。','Pressure, duration, hardening and hydration drive horizontal shear. Halide, silver, dye, latent activation and owned deposits move; later baths contact their new positions. Support/backing stay. Material leaving the frame cannot return.'),('胶片浴边界','Film bath boundary')),
 'emulsion_area_loss':(('湿乳剂缺层','Wet emulsion area loss'),('硬化提高附着阈值，湿润和热损伤降低阈值；擦伤带走成像层与已有附着物，露出支持片基，碳背层保留。缺层不能洗回，移走的物质不再参与后续药浴；后来污染仍可覆盖露出的片基。','Hardening raises adhesion; hydration and prior thermal damage lower it. Wear removes imaging layers and existing attached deposits, exposing support while preserving backing. Removed material cannot react in later baths. Later deposits can cover bare support; washing cannot restore lost emulsion.'),('指定药浴前后；旧版仅末段','Selected bath boundary; legacy terminal only')),
 'carbon_backing_routing':(('碳背层与清洗去向','Carbon backing and washing'),('预浴软化后更易松脱；换水带走松脱颗粒，含碳残液接触乳剂会再附着。残留碳增加密度，后续清洗不能恢复已排出的量。通用去附加层不自动去碳。','Prebath softening assists detachment; fresh water carries particles out, while dirty contact can redeposit them on emulsion. Retained carbon adds density. Generic auxiliary removal does not clear carbon.'),('有限碳库存','Finite carbon inventory')),
 'carbon_backing_halation':(('碳载量与曝光光晕','Carbon load and exposure halation'),('新版碳背层按初始载量和密度系数吸收双程背面回返，直接曝光和乳剂内扩散不变。期望衰减档数换算同一碳载量；更多碳也增加清洗负担及残留密度。潜影冻结后去碳不能重新产生光晕。关闭耦合保留原独立光学设置。','The new backing absorbs double-pass rear return using initial load and density. Primary exposure and emulsion scatter stay unchanged. Desired attenuation stops resolve to that same load; more carbon also increases washing demand and residual density. Removing backing after exposure cannot recreate halation. Disabling coupling preserves independent legacy optics.'),('曝光冻结／后续清洗','Frozen exposure / later washing')),
 'surface_silver_reflection':(('表面银的反射／透射','Surface silver reflection / transmission'),('同一层银的吸收和散射决定透光与反光颜色；增加散射同时减少透光。灯光、角度与粗糙度改变反光强弱，观看不改银量；漂定清除后相应反光消失。','The same silver layer partitions absorption, scattering and transmission. More scattering reduces transmitted light. Illumination, angles and roughness change its sheen; viewing never changes silver mass. Clearing removes that reflection.'),('共同光学状态','Shared optical state')),
 'surface_silver_clearing':(('表面银与后续药浴','Surface silver and later baths'),('按操作顺序处理外源银：漂白转成可定影盐，定影只去盐，直接去银移除金属银。沉积位置和后续浸润会改变最终残留。','External silver follows the sequence of later baths: bleach makes fixable salt, fixer removes salt, and direct silver removal removes metal. Deposition timing and contact change the final residue.'),('独立银／盐池','Separate metal / salt pools')),
 'silver_only_colour_clearing':(('银像材料进入彩色漂定','Silver-only stock in colour clearing'),('材料没有成像染料接替银像；漂白和定影会移走银像，充分处理可得到没有画面的片基。','No dye image replaces the silver. Bleach and fix remove the silver image; complete clearing can leave an imageless support.'),('流程消像','Image removal')),
 'intent_bypassed':(('期望总开关已关闭','Desired effects disabled'),('已旁路期望生成操作；手工药浴与事件仍执行。','Desired operations are bypassed; manual baths and events remain.'),('当前状态','Current state')),
 'development_environment':(('显影环境','Development conditions'),('时间、温度、药液和搅拌共同影响形成量与影调。','Time, temperature, chemistry and agitation jointly affect formation and tone.'),('共同条件','Shared conditions')),
 'film_reciprocity':(('曝光时长与互易律','Exposure duration and reciprocity'),('明确时长超出材料正常区间才损失有效曝光；各层响应不同会伴随偏色。期望入口线性换算平均损失档数为实际时长，不保证RGB线性。未填时长不猜测；已有潜影不重做。全部潜影前光量暂共用同一时间窗。','Explicit duration outside the stock interval reduces effective dose; unequal layer response can shift colour. Desired loss maps linearly in mean stops to duration, not RGB. Unspecified duration is not inferred; saved latent is not re-exposed. All pre-latent light currently shares one window.'),('材料响应／曝光条件','Stock response / exposure conditions')),
 'film_time_stages':(('储存、潜影与残盐','Storage, latent image and residual salt'),('曝光前储存影响感度及起始灰雾；潜影等待同时允许潜影衰退和生雾；冲洗后受光只将实际残盐转成银，不会生成染料。全部为显式时长，扫描和重开不继续老化。','Storage changes sensitivity and initial fog; latent waiting allows fading and fogging; light after processing converts actual residual salt to silver without dye. Durations are explicit; scans and reopening never advance ageing.'),('分阶段材料演变','Stage-specific material evolution')),
 'retained_bath_products':(('逐浴灰雾与颗粒','Bath fog and grain'),('化学灰雾消耗未激活银盐，并可参与彩色耦合；去银、染料侵蚀、乳剂损失会移走对应产物。局部模型按每处保留银像／染料的形成条件决定颗粒强度、尺度与团聚，最后生成一次纹理；旧模型仍取全片平均。不是逐颗粒身份或长大模拟。','Chemical fog consumes inactive halide and can couple dye. Clearing, dye attack and emulsion loss remove the corresponding products. The local model uses retained silver/dye conditions per position for grain gain, scale and clumping in one final realization; the old model uses frame averages. Individual particle identity or growth is not simulated.'),('同池形成与去除','Formation and removal in shared pools')),
 'access_and_density':(('浸润／显影抑制','Contact / inhibition'),('不均匀来自反应率差异，可能同时降低平均形成量和改变影调，并非只增加纹理。','Uneven reaction may also reduce mean formation and change tone; it is not texture alone.'),('材料池响应','Pool response')),
 'hardening_wash_damage':(('乳剂硬化','Emulsion hardening'),('硬化减轻温差损伤，同时减慢可溶残留及抑制剂的清洗；已形成的损伤不会恢复。','Hardening reduces thermal damage but slows washing of soluble residue and inhibitor; existing damage is not repaired.'),('共同材料状态','Shared material state')),
 'thermal_damage_threshold':(('温差与湿乳剂','Temperature / wet emulsion'),('清洗、含银浴或染料侵蚀浴也可能跨过损伤阈值；取决于温差、过渡时间和硬化。当前损伤仍为密度代理。','Washing, silver or dye baths may cross the damage threshold, depending on temperature change, transition time and hardening. Damage remains a density proxy.'),('阈值条件，非必然','Threshold-dependent')),
 'residue_density_and_colour':(('药液残留','Chemical residue'),('残留会同时改变密度和色彩；后续清洗去除可溶部分，结合残留保留。','Residue changes density and colour together; subsequent washing removes soluble material, while bound residue remains.'),('光学合成','Optical composition')),
 'surface_silver_density':(('旧版表面析银','Legacy surface silver'),('旧材料响应只增加银密度，受银来源和还原当量约束，不产生二向色反光，也不等同于留银冲洗。新材料可在响应编辑器中启用表面银反射。','Legacy responses add silver density, bounded by supplied silver and reducing equivalents, without dichroic reflection or bleach bypass. New materials can enable surface reflection in the response editor.'),('有限沉积量','Bounded deposition')),
 'dye_loss_remaining_image':(('染料侵蚀','Dye erosion'),('只损失现存染料；银像、盐和色罩仍保留，可能改变反差与色彩关系。清洗不能恢复已损失染料。','Only surviving image dye is lost. Silver, salts and mask remain, potentially changing contrast and colour relationships; washing cannot restore lost dye.'),('选择性材料损失','Selective material loss')),
 'no_dye_pool':(('当前流程无成像染料','No image dye in this process'),('当前材料或程序不形成染料，侵蚀不会移走银像；不同液温仍可能损伤乳剂。','The material or program forms no dye, so erosion cannot remove its silver image; temperature changes may still damage the emulsion.'),('不适用／条件关联','Not applicable / conditional')),
 'shared_bath_reactions':(('同浴多反应','Multiple reactions in one bath'),('显定同浴竞争卤化银；漂定同浴把银转为可定影盐再移除。调整一组分会改变其它组分可处理的量。','Developer/fixer competes for halide; bleach/fix converts silver to removable salt. Changing one component changes material available to the others.'),('共用物质池','Shared pools')),
 'retained_silver':(('留银冲洗','Bleach bypass'),('保留的成像银叠加在染料影像上，密度、反差及色彩表现会一起变化。新期望映射反求漂白液活性；旧配方保持原控制。','Image silver remains alongside dye, linking density, contrast and colour. New intent solves bleach activity; legacy recipes keep their original controls.'),('材料叠加／工艺映射','Material mixture / process mapping')),
 'mask_and_image_dye':(('实验性色罩漂白','Experimental mask bleach'),('去除色罩的同时可能损伤成像染料，两者比例由材料响应决定。','Mask removal may also damage image dye; their relationship is material-dependent.'),('材料选择性','Material selectivity')),
 'premature_fixing':(('提前接触定影液','Premature fixer contact'),('提前溶解未成像银盐，后续可显影量减少；已经形成的银像与染料保留。','Premature fixing removes undeveloped halide, reducing later formation while preserving existing image silver and dye.'),('不可逆池消耗','Irreversible pool loss')),
 'residual_halide':(('定影不足／缺失','Incomplete / absent fixing'),('剩余银盐进入最终光学母版；显式冲洗后受光阶段可将残盐转成银。保存后的介质不会随浏览或扫描继续变黑。','Residual halide contributes to the optical master; an explicit post-process light stage can convert it to silver. Browsing or scanning a saved medium does not darken it further.'),('残留状态','Residual state')),
 'material_process_mismatch':(('材料与工艺不匹配','Material/process mismatch'),('形成效率、各层平衡、漂定及染料稳定性可一起变化。是通用降阶兼容参数，不是按品牌拟合的交叉冲洗。','Formation, layer balance, clearing and dye stability may change together. This is generic reduced compatibility, not a brand-calibrated cross-process.'),('兼容性响应','Compatibility response')),
 'legacy_incident_multipliers':(('旧版事故兼容','Legacy incident compatibility'),('旧药染／不均可能额外放大颗粒；旧析银可被疲劳或单浴倍率放大。显式升级后改用材料操作。','Legacy stain/unevenness may amplify grain; exhaustion or monobath may amplify legacy plating. Explicit upgrade uses material operations.'),('旧算法保留','Legacy behavior')),
 'condition_variation':(('过程波动','Condition variation'),('随机变化的是工艺条件及已开启的旧效果，不是“A发生就抽签生成B”。','Conditions and enabled legacy effects vary; there is no A-triggered lottery creating effect B.'),('条件变化，非概率预报','Variation, not probability forecast')),
}

class ProcessCouplingsDialog(QtWidgets.QDialog):
    def __init__(self,config,parent=None):
        super().__init__(parent);self.setWindowTitle(text('关联影响','Linked effects'));self.resize(920,610)
        self.report=describe_process_couplings(config)
        layout=QtWidgets.QVBoxLayout(self);tabs=QtWidgets.QTabWidget();layout.addWidget(tabs)
        current=[item['code'] for item in self.report['findings']]
        for title,keys in ((text('当前条件','Current conditions'),current),(text('全部关系','All relationships'),list(LINKS))):
            table=QtWidgets.QTableWidget(len(keys),3);table.setHorizontalHeaderLabels([text('条件','Condition'),text('关联响应','Linked response'),text('性质','Type')])
            table.setEditTriggers(QtWidgets.QAbstractItemView.EditTrigger.NoEditTriggers);table.setWordWrap(True)
            font=table.font();font.setPointSizeF(10.);table.setFont(font)
            table.verticalHeader().hide();table.verticalHeader().setMinimumSectionSize(48)
            table.horizontalHeader().setSectionResizeMode(0,QtWidgets.QHeaderView.ResizeMode.Fixed);table.setColumnWidth(0,160)
            table.horizontalHeader().setSectionResizeMode(1,QtWidgets.QHeaderView.ResizeMode.Stretch)
            table.horizontalHeader().setSectionResizeMode(2,QtWidgets.QHeaderView.ResizeMode.Fixed);table.setColumnWidth(2,170)
            for row,key in enumerate(keys):
                for col,labels in enumerate(LINKS[key]):
                    item=QtWidgets.QTableWidgetItem(text(*labels));item.setToolTip(text(*labels));table.setItem(row,col,item)
            tabs.addTab(table,title);table.resizeRowsToContents()
        self.tables=[tabs.widget(i) for i in range(tabs.count())]
        tabs.currentChanged.connect(lambda index:self.tables[index].resizeRowsToContents())
        buttons=QtWidgets.QDialogButtonBox(QtWidgets.QDialogButtonBox.StandardButton.Close);buttons.rejected.connect(self.reject);layout.addWidget(buttons)

    def showEvent(self,event):
        super().showEvent(event)
        for table in self.tables:table.resizeRowsToContents()
